/**
 * An event's payload as the platform hands it over: in its own types (a [PlayerRef], an
 * entity's [UUID], a [BlockRef], a world's name), a writable field a `var` the runtime writes
 * back into, and a field costly to work out a function called only when a script listens.
 */
sealed interface GameEvent {
    /** A player joined the server. */
    data class PlayerJoin(
        /** Who it was. */
        val player: PlayerRef,
        /** Whether they have never played here before. */
        val firstJoin: Boolean,
        /** The join message everyone sees, as MiniMessage. Writable: assign another, or `nil` for none. */
        var message: String?
    ) : GameEvent

    /** A player left the server. */
    data class PlayerQuit(
        /** Who it was. */
        val player: PlayerRef,
        /** The leave message everyone sees, as MiniMessage. Writable: assign another, or `nil` for none. */
        var message: String?
    ) : GameEvent

    /** A player is saying something in chat. */
    data class PlayerChat(
        /** Who it was. */
        val player: PlayerRef,
        /**
         * What they said, as plain text: never MiniMessage, so it can be shown as it is. Writable: assign
         * other text to change what everyone sees.
         */
        var message: String,
        /**
         * How the line is shown, as MiniMessage, where `<player>` is the player's display name and `<message>`
         * what they said (both shown as they are, never read as tags). Starts as Minecraft's own look,
         * `"\\<<player>> <message>"`. Writable: assign another, like `"<gray><player>: <white><message>"`.
         */
        var format: String
    ) : GameEvent

    /** A player walked, swam, flew or fell into another block. */
    data class PlayerMove(
        /** Who it was. */
        val player: PlayerRef,
        /** Where they were, facing included: in the block they are leaving. */
        val from: Location,
        /** Where they are going, facing included: in another block from `from`. */
        val to: Location
    ) : GameEvent

    /** A player is being teleported. */
    data class PlayerTeleport(
        /** Who it was. */
        val player: PlayerRef,
        /** Where they are, facing included. */
        val from: Location,
        /**
         * Where they are going, facing included. Writable: assign another `Location` to send them there
