        /** What is in the top slot. */
        val top: ItemData?,
        /** What is in the bottom slot. */
        val bottom: ItemData?,
        /**
         * What the result slot shows, or `nil` for nothing. Writable: assign another item to make that the
         * result, or `nil` for none.
         */
        var result: ItemData?
    ) : GameEvent

    /** A player is enchanting an item. */
    data class PlayerEnchantItem(
        /** Who it was. */
        val player: PlayerRef,
        /** The enchanting table. */
        val block: BlockRef,
        /** What is being enchanted. */
        val item: ItemData,
        /** What it gets, by id with its level: `{ ["minecraft:sharpness"] = 3 }`. */
        val enchantments: Map<String, Int>,
        /** How many experience levels it takes. Writable: assign another. */
        var cost: Int
    ) : GameEvent

    /** A furnace finished smelting an item. */
    data class FurnaceSmelt(
        /** The furnace, smoker or blast furnace. */
        val block: BlockRef,
        /** What was smelted (one of it). */
        val source: ItemData,
        /** What it makes. Writable: assign another item to make that instead. */
        var result: ItemData
    ) : GameEvent

    /** A server list is asking about the server. */
    data class ServerListPing(
        /** The address it asks from, like `"203.0.113.7"`. */
        val address: String,
        /**
         * The server's description under its name (its MOTD), as MiniMessage: two lines at most. Writable:
         * assign another.
         */
        var description: String,
        /** How many players it says are on. Writable: assign another number. */
        var online: Int,
        /** How many it says fit. Writable: assign another number. */
        var maxPlayers: Int,
        /** Whether it hides the player counts (showing `???`) and who is on. Writable. */
        var hidePlayers: Boolean
    ) : GameEvent
}

/**
 * The events the server raises all the time, which the adapter listens for only while a
 * script does: the runtime says when ([Platform.watch]).
 */
enum class WatchedEvent {
    /** [GameEvents.playerChat]. */
    PLAYER_CHAT,

    /** [GameEvents.playerMove]. */
    PLAYER_MOVE,

    /** [GameEvents.playerInput]. */
    PLAYER_INPUT,

    /** [GameEvents.entityTarget]. */
    ENTITY_TARGET,

    /** [GameEvents.blockSpread]. */
    BLOCK_SPREAD,

    /** [GameEvents.blockFlow]. */
    BLOCK_FLOW,

    /** [GameEvents.blockGrow]. */
    BLOCK_GROW,

    /** [GameEvents.blockFade]. */
    BLOCK_FADE,

    /** [GameEvents.blockForm]. */
    BLOCK_FORM,

    /** [GameEvents.leavesDecay]. */
    LEAVES_DECAY,

    /** [GameEvents.blockRedstone]. */
    BLOCK_REDSTONE,

    /** [GameEvents.chunkLoad]. */
    CHUNK_LOAD,

    /** [GameEvents.chunkGenerated]. */
    CHUNK_GENERATED,

    /** [GameEvents.vehicleMove]. */
    VEHICLE_MOVE,

    /** [GameEvents.serverListPing]. */
    SERVER_LIST_PING
}

/**
 * [sink] as a server delivers to it, for a fake one: a watched event only while it is in
 * [watched], every other event always; nothing, and nothing cancelled, while there is no
 * sink.
 */
class GameEventDelivery(private val watched: Set<WatchedEvent>, private val sink: () -> GameEvents?) : GameEvents {
    override fun playerJoin(event: GameEvent.PlayerJoin) {
        sink()?.playerJoin(event)
    }

    override fun playerQuit(event: GameEvent.PlayerQuit) {
        sink()?.playerQuit(event)
    }

    override fun playerChat(event: GameEvent.PlayerChat): Boolean = WatchedEvent.PLAYER_CHAT in watched && sink()?.playerChat(event) == true

    override fun playerMove(event: GameEvent.PlayerMove): Boolean = WatchedEvent.PLAYER_MOVE in watched && sink()?.playerMove(event) == true

    override fun playerTeleport(event: GameEvent.PlayerTeleport): Boolean = sink()?.playerTeleport(event) == true

